begin;
do $test$
declare owner uuid; staff uuid; mail text; wid uuid:=gen_random_uuid(); n int; denied boolean;
begin
 select id into strict owner from auth.users where email='markcamus06@gmail.com';
 select id,email into staff,mail from auth.users where id<>owner and email_confirmed_at is not null limit 1;
 if staff is null then raise exception 'Two confirmed accounts required';end if;
 insert into public.opsfusion_workspaces(id,owner_id,name,state) values(wid,owner,'ROLLBACK ONLY staff acceptance','{"identities":[],"endpoints":[],"assets":[],"incidents":[]}');
 perform set_config('request.jwt.claim.sub',owner::text,true);
 execute 'set local role authenticated';
 perform public.opsfusion_staff_access('grant',wid,jsonb_build_object('email',mail,'role','technician'));
 execute 'reset role';
 if not exists(select 1 from public.opsfusion_audit_events where workspace_id=wid and actor_id=owner and action='Staff access grant') then raise exception 'Audit attribution missing';end if;
 denied:=false;begin perform public.opsfusion_staff_access('revoke',wid,jsonb_build_object('user_id',owner));exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'Owner revocation accepted';end if;
 perform set_config('request.jwt.claim.sub',staff::text,true);
 execute 'set local role authenticated';
 if jsonb_array_length(public.opsfusion_staff_access('list',wid))<>2 then raise exception 'Roster unavailable to technician';end if;
 if not exists(select 1 from public.opsfusion_workspaces where id=wid) then raise exception 'Technician cannot read shared workspace';end if;
 update public.opsfusion_workspaces set name='Technician edit' where id=wid;get diagnostics n=row_count;if n<>1 then raise exception 'Technician cannot update';end if;
 denied:=false;begin perform public.opsfusion_staff_access('grant',wid,jsonb_build_object('email',mail,'role','admin'));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Technician escalated role';end if;
 denied:=false;begin insert into public.opsfusion_workspaces(owner_id) values(staff);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Account auto-created workspace';end if;
 denied:=false;begin update public.opsfusion_memberships set role='admin' where workspace_id=wid and user_id=staff;exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Direct membership mutation allowed';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',owner::text,true);
 perform public.opsfusion_staff_access('grant',wid,jsonb_build_object('email',mail,'role','viewer'));
 perform set_config('request.jwt.claim.sub',staff::text,true);execute 'set local role authenticated';
 if not exists(select 1 from public.opsfusion_workspaces where id=wid) then raise exception 'Viewer cannot read';end if;
 update public.opsfusion_workspaces set name='Forbidden viewer edit' where id=wid;get diagnostics n=row_count;if n<>0 then raise exception 'Viewer updated workspace';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',owner::text,true);
 perform public.opsfusion_staff_access('revoke',wid,jsonb_build_object('user_id',staff));
 perform set_config('request.jwt.claim.sub',staff::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.opsfusion_workspaces where id=wid) then raise exception 'Revoked staff still reads workspace';end if;
 denied:=false;begin perform public.opsfusion_staff_access('list',wid);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Revoked staff still reads roster';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',owner::text,true);
 insert into public.opsfusion_employee_access(workspace_id,user_id,identity_id) values(wid,staff,'fixture');
 perform public.opsfusion_staff_access('grant',wid,jsonb_build_object('email',mail,'role','technician'));
 if not exists(select 1 from public.opsfusion_memberships where workspace_id=wid and user_id=staff) then raise exception 'Explicit portal-account membership failed';end if;
 if not exists(select 1 from public.opsfusion_employee_access where workspace_id=wid and user_id=staff) then raise exception 'Portal enrollment was lost';end if;
 if has_function_privilege('anon','public.opsfusion_staff_access(text,uuid,jsonb)','EXECUTE') then raise exception 'Anonymous execution permitted';end if;
end $test$;
rollback;
select 'PASS: shared technician access, viewer read-only, owner-only membership, no self-escalation, no workspace creation, revoke enforcement, explicit employee-to-member grant and actor audit. Fixtures rolled back.' as verification;
